const prep = $('Preparar Dados Persistência').item.json;
const pessoa = $('Upsert Contato (Pessoa)').item.json;
const msg = $('Gravar Mensagem').item.json;
const criativo = $('Upsert Criativo se Anúncio').item.json;
const sla = $('Calcular SLA se Outbound').item.json;

return {
  json: {
    ok: true,
    loja_id: prep.loja_id,
    pessoa_id: pessoa.id,
    mensagem_id: msg.id || null,
    message_id: prep.message_id,
    is_ad: prep.is_ad,
    criativo_id: msg.criativo_id || criativo.criativo_id || null,
    tempo_resposta_segundos: msg.tempo_resposta_segundos || sla.tempo_resposta_segundos || null,
    origem: prep.origem,
    tipo: prep.tipo
  }
};
